CPR.cyberware = [{"id":"c-79dcc28c","name":"Биомонитор","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Подкожный имплант, который постоянно считывает и выводит но диодный экран показания пульса, температуры, дыхания, уровень сахара в крови н т.д. Вы можете связать Биомонитор со своим Агентом, чтобы он мог отслеживать ваше состояние.","short":"Подкожный имплант, который постоянно считывает и выводит но диодный экран показания пульса, температуры, дыхания, уровень сахара в крови н т.д.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-f3c40997","name":"Химкожа","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Красители и пигменты, которые вводятся в кожу, чтобы навсегда изменить её оттенок. Сфера применения варьируется от скрытия дефектов кожи до желания иметь неоново-зеленую кожу. Пигменты, по желанию, могут быть чувствительны к температуре или реагировать на гормональные изменения в организме. Химкожа с техволосами даёт +2 к навыку Уход за Собой за наличие обоих. (Этот бонус действует 1 раз).","short":"Красители и пигменты, которые вводятся в кожу, чтобы навсегда изменить её оттенок.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Скрытность"]},{"id":"c-244dd698","name":"ЭМИ-нить","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":10,"priceLabel":"10eb (дешёвка)","humanity":0,"humanityLabel":"Нет","desc":"Эти тонкие серебряные линии, популяризованные ЮР, проходят по телу в виде дорожек. Многие считают, что они действуют как клетка Фарадея, защищая вас от радиации и электромагнитного излучения, хотя этим заявлениям нет научных подтверждений. Но выглядят они, конечно, круто. Большинство людей носят ЭМИ-нить как модный тренд.","short":"Эти тонкие серебряные линии, популяризованные ЮР, проходят по телу в виде дорожек.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-f8597475","name":"Светящиеся Тату","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Введённые под кожу элементы, которые накапливают свет и проецируют цветные татуировки. Для большой татуировки требуется установить несколько этих имплантов, чтобы завершить её. Установка 3 и более тату, даёт +2 к Навыку Гардероб и Стиль. (Этот бонус действует 1 раз).","short":"Введённые под кожу элементы, которые накапливают свет и проецируют цветные татуировки.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Социалка"]},{"id":"c-5fde205a","name":"Изменчивые такты","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Линзы в глазу, меняющие цвет. Доступны несколько моделей. Линзы могут быть чувствительны к температуре или реагировать на гормональные изменения в организме. Можно выбрать только один цвет и рисунок. Пользователь может деактивировать изменение цвета в любое время по своему желанию без каких-либо действий.","short":"Линзы в глазу, меняющие цвет.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-65a96733","name":"Подкожные Часы","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Имплантированные под кожу светодиодные часы, показывают текущее время и дату.","short":"Имплантированные под кожу светодиодные часы, показывают текущее время и дату.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-37db0181","name":"Техноволосы","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Разноцветные светящиеся искусственные волосы. Волосы могут быть чувствительны к температуре или реагировать на гормональные изменения в организме, а также по желанию удлиняться, либо втягиваться за счёт встроенного механизма. Техноволосы с Химкожей дают +2 к навыку Уход за Собой за наличие обоих. (Этот бонус действует 1 раз).","short":"Разноцветные светящиеся искусственные волосы.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-370deee8","name":"Эвристический Отслеживатель Здоровья","category":"Стилевые Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb(Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Требуется Биомонитор. Система датчиков устанавливается на теле пользователя для сбора точных данных о его здоровье. Эти данные позволяют Биомонитору отслеживать состояние тканей, плотность костей и — что наиболее популярно — последние приросты по группам мышц. Эти данные также используются для ранжирования человека с помощью запатентованной эвристики \"\"Здоровые люди\"\" (ЗЛ), которая отслеживается в режиме реального времени. Этот киберимплант позволяет персонажу сразу узнать свой уровень ПЗ.","short":"Требуется Биомонитор.","source":"ЧерныйХром","requires":["Биомонитор"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-8841715c","name":"Циферблат Убийств","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Яркие и жирные буквы, подсвеченные из-под кожи пользователя показывают \"\"ЗАМОЧИЛ:” за которыми следует число. Число указывается самостоятельно с помощью связанного агента и достигает максимального значения 999. Засчитывается как установка Светящихся Тату, что позволяет получить бонус +2 к гардеробу и стилю за наличие трех установок","short":"Яркие и жирные буквы, подсвеченные из-под кожи пользователя показывают \"\"ЗАМОЧИЛ:” за которыми следует число.","source":"ККТОК","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Социалка"]},{"id":"c-5b89c5e5","name":"Соблазнительные Ноготочки \"\"Вкл-Выкл”","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Полный набор из 10 программируемых ногтей с подсветкой позволяет пользователю воплотить в жизнь нейл-арт своей мечты. Полный набор из 10 программируемых ногтей с подсветкой позволяет пользователю воплотить в жизнь нейл-арт своей мечты. К каждой покупке прилагается набор световых ручек для создания новых заготовок для нейл-арта. Предустановки также можно загрузить из Городской Сети с помощью подключенного агента. Засчитывается как установка стилевого импланта Светящиеся Тату, что помогает получить бонус +2 к гардеробу и стилю при наличии трех подобных установок. Может быть установлена как на мясных, так и на кибернетических руках.","short":"Полный набор из 10 программируемых ногтей с подсветкой позволяет пользователю воплотить в жизнь нейл-арт своей мечты.","source":"ККТОК","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Нетраннинг","Социалка"]},{"id":"c-f95a8216","name":"Глаза Настроения","category":"Стилевые Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":0,"humanityLabel":"Нет","desc":"Имплантированные в глаз линзы, меняющие цвет. Цвет глаз носителя меняется в зависимости от самой большой характеристики его текущего настроения, полученной в результате сканирования мозга, записанного Нейролинком Красный = злоба, синий = грусть, желтый = страх. Розовый = раздражение, зеленый = ревность, серый = смерть. Подделать сканирование эмоций настолько безупречно, чтобы изменить цвет глаз во время их ношения — это проверка навыка Актёрского Мастерства СЛ21. Может быть отключено пользователем в любое время без действия. Требуется Нейролинк.","short":"Имплантированные в глаз линзы, меняющие цвет.","source":"ККТОК","requires":["Нейролинк"],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие","Социалка"]},{"id":"c-52ef2c5c","name":"Нейролинк","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Проводная искусственная нервная система. Требуется для использования нейроимплантов и смартлинга. Имеет 5 слотов опций.","short":"Проводная искусственная нервная система.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":5,"role":null,"tags":[]},{"id":"c-7cd6e9cc","name":"Записыватель брейндансов","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Нейролинка. Поделись пережитой историей с собственной точки зрения! Записывает Брейндансы на стандартную щепку памяти или на подсоединенный Агент. Брейндансы можно просматривать через очки для брейнданса. Требует нейролинк.","short":"Опция Нейролинка.","source":"КорБук","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-e2d14e11","name":"Сопроцессор Рефлексов","category":"Нейронные Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Опция Нейролинка. Позволяет пользователю уклоняться от пуль без РЕА 8+","short":"Опция Нейролинка.","source":"ЧерныйХром","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-d1725cca","name":"Транс Смерти","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Нейролинка. При активации Действием сердцебиение, дыхание и другие жизненные показатели пользователя замедляются до практически неощутимой скорости. Внешне пользователь выглядит функционально мертвым и получает -4 ко всем Действиям. Пока Транс Смерти активен, и пользователь активно притворяется мертвым, его жизненные функции могут быть обнаружены только с помощью проверки СЛ17 Медицинских Технологий, или СЛ21 Криминологии, Дедукции, или Внимательности. Из состояния Транса Смерти пользователь может выйти в любой момент без каких-либо Действий. Повторное использование может навсегда повлиять на бледность кожи.","short":"Опция Нейролинка.","source":"12 Дней КиберРождества","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие","Мобильность"]},{"id":"c-52b92d6e","name":"Личный порт","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Нейролинка. Разъём, установленный в запястье или голову, позволяет подключаться и использовать Умное оружие, Кибердеки, тяжёлую технику и управлять транспортом без рук. Если установить несколько личных портов, то можно будет подключаться к нескольким вещам одновременно. Требует нейролинк.","short":"Опция Нейролинка.","source":"КорБук","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Нетраннинг"]},{"id":"c-42628df9","name":"Керензиков","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Опция Нейролинка. Ускоритель Всегда работающий Ускоритель, который увеличивает скорость реакции. Даёт +2 к броскам Инициативы. Одновременно может быть установлен только один Ускоритель. Требует нейролинк.","short":"Опция Нейролинка.","source":"КорБук","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-ebcc8f02","name":"Сандевистан","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Нейролинка. Ускоритель Ускоритель, который даёт кратковременное улучшение, значительно увеличивающее скорость реакции. При активации (Действие), в течение минуты даёт +3 к Инициативе. Повторно активировать можно только через час. Одновременно может быть установлен только один Ускоритель. Требует нейролинк.","short":"Опция Нейролинка.","source":"КорБук","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-505ddc02","name":"Управление Дронами","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Нейролинка. Gозволяет пользователю мысленно контролировать своих дронов, как если бы он это делал через Агент. Пользователь все еще должен подключаться к Дрону, следуя нормальным правилам, как определено по его типу, будь то с помощью Связывания или Перехвата. Специализированные антенны Управления Дронами увеличивает диапазон, в котором пользователь может управлять беспилотником до 20 м/ярдов, если обычный диапазон управления составляет 20 м/ярдов, или меньше.","short":"Опция Нейролинка.","source":"Hope Reborn+","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-cbcbecc9","name":"Бюджетный разъем для щепок","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Нейролинка. Разъём устанавливается в заднюю часть шеи, в него легко вставляется одно Щепка (которых существует различное множество). Чтобы вставить или достать одну Щепку, необходимо потратить Действие. Если вы впервые вставляете Щепку (которую до этого не использовали), вы теряете Человечность. Если вы ранее использовали Щепку, то Человечность не теряется. Щепка не занимает слот модуля в Нейролинке. Можно установить несколько разъемов, но каждый из них должен оплачивается отдельно. Всякий раз, когда вы получаете повреждение в области головы, Разъем для Щепок яростно выбрасывает установленную Щепку. Выброшенная Щепка летит за вами на расстояние до 30 м. Бросьте 1d10. При 1 Щепка уничтожается в полете. Щепку всегда легко обнаружить по её дымящимся раскаленным краям.","short":"Опция Нейролинка.","source":"ЧерныйХром","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-244d9e49","name":"Разъём для Щепок","category":"Нейронные Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Нейролинка. Разъём устанавливается в заднюю часть шеи, в него легко вставляется одно Щепка (которых существует различное множество). Чтобы вставить или достать одну Щепку, необходимо потратить Действие. Если вы впервые вставляете Щепку (которую до этого не использовали), вы теряете Человечность. Если вы ранее использовали Щепку, то Человечность не теряется. Щепка не занимает слот модуля в Нейролинке. Можно установить несколько разъемов, но каждый из них должен оплачивается отдельно. Требует нейролинк.","short":"Опция Нейролинка.","source":"КорБук","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-7abbe0b7","name":"Щепка памяти","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":10,"priceLabel":"10eb (дешёвка)","humanity":0,"humanityLabel":"Нет","desc":"Щепка для хранения данных. При установке в Разъём, на можно поместить какую-либо информацию или изучить то, что уже хранится на ней. Требует Разъём для Щепок.","short":"Щепка для хранения данных.","source":"КорБук","requires":["Разъём для Щепок"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-2d557676","name":"Химический анализатор","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Щепка. При установке в Разъём позволяет анализировать вещество. Нужно Действие, чтобы определить точный химический состав вещества. Мгновенно определяет большинство веществ из обширной базы образцов. Требует Разъём для Щепок.","short":"Щепка.","source":"КорБук","requires":["Разъём для Щепок"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-9f1cf203","name":"Усилитель обоняния","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Щепка. При установке в Разъём обоняние пользователя усиливается, что позволяет ему использовать навык Выслеживание, используя запах в дополнение к визуальным подсказкам. Требует Разъём для Щепок.","short":"Щепка.","source":"КорБук","requires":["Разъём для Щепок"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-22b6e7ff","name":"Редактор боли","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Щепка. При установке в Разъём, отключает болевые рецепторы, позволяя игнорировать последствия Тяжёлого Ранения. Требует Разъём для Щепок.","short":"Щепка.","source":"КорБук","requires":["Разъём для Щепок"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-7a05e070","name":"Щепка навыка","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":1000,"priceLabel":"1000eb (О.дорогое),500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Щепка. При установке в Разъем чип фиксирует навык, для которого он был создан, у пользователя на значение 3, если только навык пользователя не был уже натренирован выше 3, в этом случае ничего не происходит. Чипы умений для сложности (х2) стоят 1,000еЬ, для всех остальных умений — 500еЬ. Требует Разъём для Щепок.","short":"Щепка.","source":"КорБук","requires":["Разъём для Щепок"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-7936c737","name":"Тактильное усиление","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Щепка. При установке в Разъём усиливает осязательные чувства. Дотронувшись до поверхности, пользователь может почувствовать движение в пределах 20 метров от себя. Пока рука используется в качестве “детектора движения\", её нельзя использовать ни для чего другого. Требует Разъём для Щепок.","short":"Щепка.","source":"КорБук","requires":["Разъём для Щепок"],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-65084e78","name":"Позер Чип","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":1000,"priceLabel":"1000eb (О.дорогое),500eb (Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Щепка. Не просто выглядите как Элвис. Будьте Элвисом. Или кем-то другим, чьим двойником хотите быть. Щепка. Чип, перегруженный схемами обратной связи, заставляет пользователя подсознательно копировать голосовые паттерны, нервные жесты и язык тела записанной в нем личности. Если чип установлен в Разъем для Щепок, он дает пользователю +4 к проверкам Актерского Мастерства, чтобы выдать себя за персонажа. Если Персонаж не борется с чипом, а Игрок отыгрывает олицетворение, этот бонус к проверкам Актерского Мастерства увеличивается до +5. Позер Чипы, основанные на известных личностях и созданные с использованием сотен часов общедоступного видеоматериала, стоят 500eb. Чипы, созданные на основе частных лиц с использованием не менее 10 часов отснятого материала, стоят 1,000eb.","short":"Щепка.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие","Социалка"]},{"id":"c-29d4b6b8","name":"Поведенческий Чип: Животное","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Щепка. Каждый чип имеет отпечаток одного вида или породы животных и перегружен схемами обратной связи, заставляя пользователя подсознательно имитировать поведение психики животного, отпечатанной на нем. Поведенческий Чип не отменяет способность пользователя произносить слова или выполнять более «человеческие» действия, но подталкивает его к тому, чтобы при любой возможности вести себя по-животному, будь то прерывание разговора, чтобы погнаться за лазерной указкой, скользящей пополу, или попытка поприветствовать кого-то, обнюхав егозадницу. При установке в Разъем для Щепок Поведенческий Чип дает пользователю +4 к проверкам актерского мастерства для имитации поведения животного, но не его тела - для этого им понадобится Экстремальный Биоскульпт.","short":"Щепка.","source":"Мешай Напитки","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие","Социалка"]},{"id":"c-9f2f6be8","name":"Чип переводчик","category":"Нейронные Импланты","place":"—","surgeryDV":0,"installCost":0,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Компания Raven Microcyb только что выпустила на рынок эти шикарные устройства. Устройства для перевода в режиме реального времени. Когда вы видите или слышите слова, чип переводит их на выбранный вами язык и проецирует текст на ваш Хирон. Щепка. Требуется Хирон. Любые слова на языке, которые слышит или читает пользователь, переводятся на выбранный вами язык и отображаются на Хироне в виде субтитров в режиме реального времени. По усмотрению Рефери, редкие «мертвые» языки или языки и диалекты, на которых говорят небольшие и/или изолированные группы населения, чип не может перевести. Перевод сленговых терминов осуществляется с перебоями, поскольку язык развивается быстрее, чем Raven Microcybernetics успевает выпускать обновления. Чип-переводчик не позволяет пользователю говорить на каких-либо дополнительных языках.","short":"Компания Raven Microcyb только что выпустила на рынок эти шикарные устройства.","source":"Действуем Тихо","requires":["Хирон"],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-597f86ba","name":"Киберглаз","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Все перечисленные ниже модули устанавливаются в искусственный глаз, которым заменяется мясной. Каждый киберглаз имеет 3 слота для модулей. Некоторые модули должны быть сопряжены. (Купленный дважды и установленные в разные глаза. Потеря Человечности рассчитывается отдельно для каждого модуля).","short":"Все перечисленные ниже модули устанавливаются в искусственный глаз, которым заменяется мясной.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":3,"role":null,"tags":[]},{"id":"c-4a446e87","name":"Анти-ослепление","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Пользователь невосприимчив к слепоте или другим эффектам, вызванными яркими вспышками, например, светошумовыми гранатами. Требуется два сопряженных Киберглаза.","short":"Модуль Киберглаза.","source":"КорБук","requires":["2× Киберглаз","Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-11318a6d","name":"Хирон","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Проецирует крошечный экран в поле зрения для сообщений, видео и т.д. от других киберимплантов и электроники пользователя. “Картинка в картинке\" в реальной жизни. Требуется Киберглаз.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-f9a2ea74","name":"Сдвиг Цвета","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Косметическое улучшение, позволяющее сколько угодно раз менять цвета и узоры в глазу (Действие). Глаза могут быть чувствительны к температуре или реагировать на гормональные изменения в организме. Требуется Киберглаз.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-3b6f7b70","name":"Дартган","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Зкзотическое Оружие Дартган, спрятанное внутри киберглаза, рассчитанное на один выстрел. Требуется Киберглаз и 3 слота модулей.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-f69a4563","name":"Усилитель Картинки","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберглаза. Пользователь добавляет +2 к навыкам Внимательности, Чтения по губам и Скрытие/раскрытие объекта при проверках, требующих зрения. Требуется два сопряженных Киберглаза. Многократные установки не дают никаких преимуществ","short":"Модуль Киберглаза.","source":"КорБук","requires":["2× Киберглаз","Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие","Скрытность"]},{"id":"c-7477624f","name":"Слабое освещение/ИК/УФ","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберглаза. Снимает штрафы, накладываемые темнотой, дымом, туманом и т.п. до 0. Пользователь может отличить горячее мясо от холодного металла , но не позволяет видеть сквозь укрытия. Требуется два сопряженных Киберглаза и занимает 2 слота опций в каждом глазе.","short":"Модуль Киберглаза.","source":"КорБук","requires":["2× Киберглаз","Киберглаз"],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-7a83a3d0","name":"Микро-Оптика","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Микроскоп, позволяющий рассматривать предметы с увеличением до 400х. Требуется Киберглаз.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-d5ae8fb8","name":"Микро-видео","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Записывает видео и аудио но стандартную щепку памяти или связанный агент. Требуется Киберглаз и 2 слота модулей.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-6521b187","name":"Детектор радиации","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберглаза. Отображает в пределах 100м от пользователя радиацию в виде голубого свечения над её источником. Требуется Киберглаз.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-21c6c2a0","name":"Тактический прицел","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберглаза. Даёт пользователю +1 к проверкам Прицельного выстрела. Множественные установки не суммируются. Требуется Киберглаз.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-f0cf3d51","name":"Теле-оптика","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберглаза. Позволяет видеть детали но расстоянии 800м. При атаке цели но расстоянии 51ми дольше в режиме одиночного огня или прицельного выстрела можете добавить +1 к проверке. Несколько установок не суммируются. Не суммируется со снайперским прицелом. Требуется Киберглаз.","short":"Модуль Киберглаза.","source":"КорБук","requires":["Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Восприятие"]},{"id":"c-10ba51a6","name":"Виртуальное зрение","category":"КиберОптика","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберглаза. Проецирует изображение киберпространства поверх реального мира. Теперь точно не забудете свои Очки Виртуальности. Требуется два сопряженных Киберглаза.","short":"Модуль Киберглаза.","source":"КорБук","requires":["2× Киберглаз","Киберглаз"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-7ea137cf","name":"Укрепленный Корпус Киберглаза","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Защита от ЭМИ эффектов","short":"Защита от ЭМИ эффектов","source":"ЧерныйХром","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-08392a3f","name":"Спонсируемый Киберглаз","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":50,"priceLabel":"50(Ценное)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Дешевый киберглаз с Хироном и кучей рекламы.","short":"Дешевый киберглаз с Хироном и кучей рекламы.","source":"ЧерныйХром","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-49d894b0","name":"Хранилище щепок","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Киберглаза. Отдел может скрывать до четырёх щепок без необходимости совершать проверку. Щепки можно легко вытащить, Действием повернув глаз в глазнице. Требует Киберглаз и занимает 3 слота опций.","short":"Опция Киберглаза.","source":"Микрохром","requires":["Киберглаз"],"body":null,"slots":3,"capacity":null,"role":null,"tags":[]},{"id":"c-b260256b","name":"Hello Cutie sparkle-ize","category":"КиберОптика","place":"Клиника","surgeryDV":15,"installCost":500,"price":250,"priceLabel":"250eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Киберглаза. Требует 2 слота модификаций. Фонарик (см. CP:R стр. 353) встроенный в глаз. Если данная опция спаренная, то можно ослепить цель с работающими «мясными» глазами или киберглазами в радиусе 25 м (12 клеток). Цель делает Проверку Сопротивления пыткам/наркотикам СЛ 15. Если провалит — получает Критическую травму \"Повреждение глаза\" на 1 минуту. Данное Действие не требует Проверок от игрока. Защита, такая как Опция киберглаз \"Антиослепление\", нейтрализует эффект.","short":"Опция Киберглаза.","source":"THE 12 DAYS OF CUTIEMAS","requires":["Киберглаз"],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-7eb754be","name":"Комплекс Кибераудио","category":"КиберАудио","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Комплект Кибераудио незаметно устанавливается во внутреннюю часть черепа. Имеет 3 слота для модулей Кибераудио. Можно установить только один Набор Кибераудио.","short":"Комплект Кибераудио незаметно устанавливается во внутреннюю часть черепа.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":3,"role":null,"tags":["Восприятие","Скрытность"]},{"id":"c-9f5468c3","name":"Усиленный слух","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Кибераудио. Даёт пользователю +2 к проверке навыка Внимательность, если задействован слух. Требуется Комплект Кибераудио. Установка нескольких модулей не даёт никаких преимуществ.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-cdf8af56","name":"Аудио рекордер","category":"КиберАудио","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Записывает аудио на стандартную Щепку Памяти или подключённый Агент. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-ee9c6913","name":"Детектор жучков","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Устройство пищит, когда находится в 2 метрах от прослушки, жучка или иного подслушивающего устройства. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-8865ca34","name":"Трекер маячков","category":"КиберАудио","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Отслеживает привязанный маячок на расстоянии до 1,5 километров. В комплект входит привязанный маячок размером с пуговицу. Дополнительный маячок стоит 50еЬ. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-58dae524","name":"Внутренний агент","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Кибераудио. Полноценный Агент (см. раздел \"снаряжение\"на СТР. 352), управляемый с помощью голоса. Весь контент озвучиваются, но можно вывести на модуль Хирон или на ближайший экран. Щепка Памяти имплантированного Агента не может быть извлечена без хирургического вмешательства. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-b0b7f6ae","name":"Демпфер","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Автоматическая коррекция звука. Пользователь невосприимчив к оглушению или другим эффектом, вызванными громкими звуками, например светошумовыми гранатами. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-04561ff4","name":"Коммуникатор","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Позволяет общаться по радиосвязи в радиусе 1 километра. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-ff3ee9c1","name":"Радиосканер/проигрыватель","category":"КиберАудио","place":"Клиника","surgeryDV":15,"installCost":500,"price":50,"priceLabel":"50eb (ценное)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. С помощью действия, можно сканировать все радиочастоты в радиусе километра, которые сейчас работают, и настроиться на них. Чтобы слушать самую крутую музыку, Проигрыватель можно подключать к Дата Пулу или включить её с Щепки. Для прослушивания зашифрованных радиостанций нужен \"Шифратор/ Дешифратор\". Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-2450a835","name":"Радар детектор","category":"КиберАудио","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Начинает пищать, если в радиусе 100 метров замечает активный радар. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-74c02ca6","name":"Шифратор/дешифратор","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Кибераудио. Позволяет шифровать исходящие сообщения, чтобы их нельзя было понять без дешифровки. Дешифратор также входит в комплект без дополнительной оплаты. Требуется Комплект Кибераудио.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-28dda183","name":"Анализатор голосового стресса","category":"КиберАудио","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Кибераудио. Дает +2 к Навыкам “Проницательность” и “Допрос”. Потратив Действие, можно на минуту активировать функцию “Детектор лжи”. В течении этого времени ГМ скрытно бросает за игрока все проверки “Проницательность” и “Допрос”, и когда фиксирует ложь, подает один звуковой сигнал, или когда сам того захочет если бросок был неудачным. Остерегайтесь ложных, положительных и отрицательных результатов. Требуется Комплект Кибераудио. Установка нескольких модулей не дает преимущества.","short":"Модуль Кибераудио.","source":"КорБук","requires":["Комплект Кибераудио"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие","Скрытность"]},{"id":"c-d5776fa4","name":"Комплект КиберАудио по скидке","category":"КиберАудио","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Комплект Кибераудио с большим и заметным внеш- ним компонентом, установленным вокруг ушей поль- зователя. Он имеет всего 1 слот для опции Кибераудио. У пользователя может быть установлен только один Комплект Кибераудио.","short":"Комплект Кибераудио с большим и заметным внеш- ним компонентом, установленным вокруг ушей поль- зователя.","source":"ЧерныйХром","requires":[],"body":null,"slots":0,"capacity":1,"role":null,"tags":["Восприятие"]},{"id":"c-7134e2ea","name":"Автоинъектор Бодивейт","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Внутренний Киберимплант. Можно ввести одну дозу Уличного Наркотика в подкожный резервуар в качестве действия. После ввода пользователь может совершить действие, чтобы ввести уличный наркотик в свое тело. Пользователь с Биомонитором может запрограммировать автоинъектор на автоинъекцию препарата при броске Инициативы, получении критической травмы или определённом состоянии ранения.","short":"Внутренний Киберимплант.","source":"АптекаХорнета","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Мобильность","Нетраннинг"]},{"id":"c-504f908c","name":"АудиоВокс","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Вокальный синтезатор. +2 к навыку актёрского мастерство и +2 к навыку Актерское мастерство и +2 к навыку Игра на инструменте (пение). Установка нескольких имплантов не даёт никаких преимуществ.","short":"Вокальный синтезатор.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие","Социалка"]},{"id":"c-4b0fe6fe","name":"Вампиры","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Вживленные клыки во рту пользователя. Лёгкое оружие ближнего боя отличного качество (1d6 урона, 2 СКА), которое можно прятать без проверки. Пузырёк с Ядом или Биотоксином (приобретается отдельно, см. список снаряжения но СТР. 355), можно (без проверки) надежно хранить и прятать во рту рядом с клыками. Содержимое пузырька применяется к Вампирам бесшумно и в любой момент (Действие не тратится). Каждое применение тратит весь пузырёк, эффект длится 30 минут. Установка Вампиров включает в себя полную переработку рта пользователя, что предотвращает случайное отравление клыками на полпути к куску пиццы или от критической неудачи.","short":"Вживленные клыки во рту пользователя.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-d24679a0","name":"Водительский Ошейник","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Иммунитет к Критической Травме \"Перелом Шеи”","short":"Иммунитет к Критической Травме \"Перелом Шеи”","source":"ЧерныйХром","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-56bc1cf9","name":"Жабры","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Пользователь может дышать под водой","short":"Пользователь может дышать под водой","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-19a16b78","name":"Искусственные мышцы и усиленные кости","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Увеличивает ТЕЛ пользователя на 2. Это увеличение ТЕЛ влияет на ПЗ, Порог Ранения и Спасбросок от Смерти. Повторная установка суммируется. Нельзя повысить ТЕЛ выше 10.","short":"Увеличивает ТЕЛ пользователя на 2.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-223355c9","name":"Контрацептив","category":"Внутренние Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":10,"priceLabel":"10eb (дешёвка)","humanity":0,"humanityLabel":"Нет","desc":"Предотвращает нежелательную беременность.","short":"Предотвращает нежелательную беременность.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-c3c4ec34","name":"Киберзмея","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Оружие. Жутковатое щупальце, расположенное в горле/пищеводе. Очень Тяжелое Оружие Ближнего Боя (4d6, 1 СКА), можно успешно скрыть без проверки.","short":"Оружие.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Скрытность"]},{"id":"c-e642803d","name":"Киберпечень от Hammered Industries","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Внутренний Киберимплант. Пользователь получает +6 к проверкам Сопротивление пыткам/наркотикам при сопротивлении опьяняющему воздействию алкоголя и имитирующих алкоголь веществ, таких как кармотрин. Оно не добавляется к проверкам Сопротивление/Пыткам наркотиков, сделанным против СЛ вторичного эффекта уличного наркотика, даже если наркотик содержит алкоголь или кармотрин. Многократные установки не дают пользователю никаких дополнительных преимуществ, и его эффект не суммируется с другими бонусами к проверкам Сопротивление пыткам/наркотикам, например, полученным от связывателей токсинов.","short":"Внутренний Киберимплант.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-848125a4","name":"Киберчереп","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":5000,"priceLabel":"5000eb (Роскошь)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Является Внутренним Имплантом. Занимает 3 слота. Голова больше не считается слабым местом при прицельном выстреле или в любом другом случае. Кроме того, пользователь невосприимчив к эффекту и бонусному урону от травм \"\"Перелом черепа\"\" и \"\"Сломанная челюсть\"\". К каждому Киберчерепу прилагается персонализированная лицевая панель. Дополнительные персонализированные лицевые пластины, в том числе покрытые RealskinnTM и SuperChrome®, доступны за 100еб (Премиум).","short":"Является Внутренним Имплантом.","source":"ПНМ","requires":[],"body":null,"slots":3,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-1342205e","name":"Назальные фильтры","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Вы становитесь невосприимчивы к воздействию токсичных газов, дыма и всех других опасностей, которые вы вдыхаете. При желании можно выключить назальные фильтры не тратя Действие.","short":"Вы становитесь невосприимчивы к воздействию токсичных газов, дыма и всех других опасностей, которые вы вдыхаете.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-74bf9f86","name":"Наноматрица Травматической Реакции","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Внутренний Киберимплант. Один раз в день, в качестве действия, активируйте восстановление вашей Тканекожи или Подкожной Брони до полного ОС. Требуется Тканекожа или Подкожная Броня. Каждая дополнительная установка увеличивает ежедневное использование на 1","short":"Внутренний Киберимплант.","source":"ЧерныйХром","requires":["Тканекожа"],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-6bca3f30","name":"НеоЯзык","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Внутренний Киберимплант. Кибер-язык изменяет чувство вкуса пользователя. С помощью подключенного агента в пищу можно добавлять виртуальные приправы. Может быть деактивирован пользователем в любое время без каких-либо действий, устраняя любое чувство вкуса пользователя.","short":"Внутренний Киберимплант.","source":"ККТОК","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-8a88e635","name":"Независимая подача воздуха","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Баллона хватает но 30 минут, повторное наполнение из окружающей среды занимает 1 час. Другой вариант — заменить пустой баллон на полный (50еЬ) потратив Действие.","short":"Баллона хватает но 30 минут, повторное наполнение из окружающей среды занимает 1 час.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-29ed2239","name":"Огненное Дыхание","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Внутренний Киберимплант. Требуется 2 Слота Опций. Экзотический дробовик, установленный в горле пользователя, стреляет при открытии рта и вытягивании языка. Он несовместим со всеми модификациями оружия и может заряжаться только одним зажигательным снарядом. Это требует полной перестройки рта, носа и горла для защиты от случайного проглатывания огня. Огненное Дыхание может быть успешно скрыто без проверки.","short":"Внутренний Киберимплант.","source":"Биоэкзоты","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Защита","Скрытность"]},{"id":"c-1668eb0c","name":"Полуночница сексуальный имплант","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Будь Венерой, будь огнем. Будь желанием.","short":"Будь Венерой, будь огнем.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-3ebcea52","name":"Мр. Перчик Сексуальный имплант","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Всю ночь, каждую ночь. И оно никогда не узнает.","short":"Всю ночь, каждую ночь.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-8f07d0a0","name":"Связыватель токсинов","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Добавляет пользователю + 2 к Навыку “Сопротивление Пыткам/Норкотикам\". Установка нескольких имплантов не даёт никаких преимуществ.","short":"Добавляет пользователю + 2 к Навыку “Сопротивление Пыткам/Норкотикам\".","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-bb32efc6","name":"Радар/Сканер","category":"Внутренние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Постоянно сканирует местность в радиусе 50 метров от пользователя, в т.ч. под водой. Сканирование не показывает ничего за укрытием или закрытой дверью. Пользователь получает звуковой сигнал от мастера вместе с направлением его источника всякий роз, когда при сканировании обнаруживается новый движущийся объект. Нельзя получить эффект дважды.","short":"Постоянно сканирует местность в радиусе 50 метров от пользователя, в т.ч.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие","Мобильность"]},{"id":"c-8ed3c398","name":"Регулятор Голода","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Внутренний Киберимплант. Позволяет управлять голодом и игнорировать его одним нажатием кнопки, используя свой биомонитор. Что позволяет пользователю игнорировать ПЧ от Долговременных Факторов стресса связанных с голоданием. Сам голод все еще является проблемой. После семи дней без пищи пользователь должен делать спасбросок смерти в начале каждого дня с накапливающимся штрафом +1 к броску за каждый дополнительный день. Требуется Биомонитор.","short":"Внутренний Киберимплант.","source":"ККТОК","requires":["Биомонитор"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-479424a7","name":"Усиленные антитела","category":"Внутренние Импланты","place":"Молл","surgeryDV":13,"installCost":100,"price":500,"priceLabel":"500eb (Дорогое)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"После стабилизации, за каждый день отдыха, благодаря этому импланту, восполняется здоровье равное удвоенному ТЕЛ (вместо обычного темпа), большую часть дня надо отдыхать, заниматься можно только легкой активностью, пока Здоровье полностью не восполнится.","short":"После стабилизации, за каждый день отдыха, благодаря этому импланту, восполняется здоровье равное удвоенному ТЕЛ (вместо обычного темпа), большую часть дня надо","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-35746010","name":"Экранирование Внутренних имплантов","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Все внутренние кибер-импланты пользователя укреплены в соответствии с военными стандартами и не могут быть выведены из строя, отключены или уничтожены электрическим током, Микроволновкой или ЭМИ-импульсом, а также любым программным воздействием (кроме Черного ЛЬДА).","short":"Все внутренние кибер-импланты пользователя укреплены в соответствии с военными стандартами и не могут быть выведены из строя, отключены или уничтожены электриче","source":"ЧерныйХром","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Нетраннинг"]},{"id":"c-c0b79257","name":"Хотсвап крепление Лицевой Панели","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Нужна новая внешность для горячего свидания? Конечно, можно попросить своего Фиксера достать тебе место в бодискульптурной клинике. Но умный, стильный и современный модник знает — скальп остался в прошлом. Настоящие иконы стиля покупают кастомные лицевые панели под каждый случай жизни. Один имплант — бесконечные образы. Новый ты — хоть каждый день недели. Внутренний Киберимплант. Заменяет твоё мясное лицо на быстросъёмное крепление, к которому можно присоединить лицевую панель. Панель можно установить или снять действием. В комплекте — одна персонализированная панель. Дополнительные панели, включая модели с покрытием Realskinn™ и SuperChrome®, можно приобрести отдельно за 100eb (премиум).","short":"Нужна новая внешность для горячего свидания?","source":"THE 12 DAYS OF REDMAS","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-db6d23ad","name":"Sycust Киберпозвоночник","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Твой позвоночник — слишком ценная штука. Тебе нужна неуязвимость металла. Тебе нужен киберпозвоночник. Военный стандарт, двойные стенки, улучшенная подвижность — и, по отчётам, 80% пользователей утверждают, что «всё оправдало ожидания или превзошло их». Внутренний киберимплант. Требует 3 слота. Позволяет полностью игнорировать эффект и дополнительный урон от Критической Травмы \"Перелом Позвоночника\". Киберпозвоночник усиленный — он невосприимчив к повреждениям и выводу из строя от ЭМИ-эффектов вроде микроволновых импульсов или программ (если это не Чёрный ЛЁД). Дополнительно: пользователь получает +1 к проверкам навыка \"Акробатика\". Позвоночник Sycust также служит точкой выхода для киберзмеи (место выбирает пользователь — откуда по позвоночнику она вылезает).","short":"Твой позвоночник — слишком ценная штука.","source":"THE 12 DAYS OF REDMAS","requires":[],"body":null,"slots":3,"capacity":null,"role":null,"tags":["Бой","Мобильность","Нетраннинг"]},{"id":"c-1bcc2472","name":"КиберПроводник Zetatech, Встроенный","category":"Внутренние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Боргирование. Внутренний киберимплант. Требует 3 слота. Устанавливается только в рамках Полной Конверсии Тела. Интегрированный Киберпроводник от Zetatech встраивается прямо в тело ПКТ (Полная Конверсия Тела). Помимо доступа ко всем кибердекам, установленным в сам Киберпроводник, устройство также соединяет любые другие кибердеки, встроенные в тело ПКТ, с Киберпроводником — позволяя пользователю переключаться между всеми кибердеками через этот интерфейс. При этом пользователь не получает урон при переключении между кибердеками через интегрированный Киберпроводник. Все кибердеки, установленные в интегрированную версию устройства, считаются частью полной конверсии и могут взаимодействовать с другим специализированным боргированием — например, интегрированным покрытием тела ПКТ. У пользователя может быть только один Киберпроводник.","short":"Боргирование.","source":"THE 12 DAYS OF REDMAS","requires":["ПКТ"],"body":null,"slots":3,"capacity":null,"role":null,"tags":["Бой","Нетраннинг"]},{"id":"c-6ae559de","name":"Боевой Хвост","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Внешний Киберимплант. Требуется 2 Слота Опций. Позвоночник пользователя удлиняется, чтобы соединить нервы с вооруженным хвостовым модулем. Требует Нейролинк. Хвост функционирует как Тяжелое Оружие Ближнего Боя. По усмотрению ГМ персонаж может использовать свой боевой хвост для других целей, кроме нанесения ударов противнику, со штрафом -4 При таком применении боевой хвост не может быть использован в качестве оружия.","short":"Внешний Киберимплант.","source":"Биоэкзоты","requires":["Нейролинк"],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-d6d09115","name":"Боевая Челюсть","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Требуется 2 Слота Опций. Челюсть пользователя заменяется на огромную гид- равлическую челюсть, способную наносить сокруши- тельные удары двумя рядами усиленных зубов. Боевая челюсть функционирует как Очень Тяжелое Оружие Ближнего Боя.","short":"Требуется 2 Слота Опций.","source":"Биоэкзоты","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-50c25b35","name":"Кироши ОптиЩит","category":"Внешние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Внешний Киберимплант. В брови встроены выдвижные ротивоослепляющие зеркальные очки, которые можно выдвигать или убирать Действием. При выдвинутых очках пользователь невосприимчив к слепоте или другим эффектам, вызванным опасными вспышками света, такими как светошумовая граната.","short":"Внешний Киберимплант.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-bb01c050","name":"Наружный Видеоэкран","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100eb (Премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Гибкая прямоугольная сенсорная телевизионная панель Ню-Тек размером примерно с основную книгу правил Cyberpunk RED устанавливается под кожу, превращая любую желаемую часть тела пользователя в экран, который может быть использован связанным агентом или щепкой памяти, вставленной в имеющийся у пользователя разъём для щепок.","short":"Гибкая прямоугольная сенсорная телевизионная панель Ню-Тек размером примерно с основную книгу правил Cyberpunk RED устанавливается под кожу, превращая любую жел","source":"ККТОК","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Восприятие"]},{"id":"c-94461ee0","name":"Подкожный карман","category":"Внешние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Размер 5x10 см с молнией Realskinn™. Содержимое можно успешно скрыть без проверки.","short":"Размер 5x10 см с молнией Realskinn™.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Скрытность"]},{"id":"c-8cf6cc70","name":"Подкожная броня","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Тело и голова бронированы всегда на уровне ОС 11. Ваша ОС определяется самым высоким предметом брони. Кроме того, всякий раз, когда ваша получает урон в каком-либо месте, все ваши предметы брони в этом месте получают урон одновременно (например, тканекожа головы и шлем). Когда вы успешно завершаете 1 день отдыха (исцеления), наномашины, присутствующие в подкожной броне, восстанавливают 1 ОС тела и головы.","short":"Тело и голова бронированы всегда на уровне ОС 11.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Защита"]},{"id":"c-eb6e3ca3","name":"Сайкаст плетеная кожа","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (О.Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Лучшая Подкожная Броня, чем все остальные на рынке. Внешний киберимплант. Подкожная броня. Тело и голова пользователя бронированы на ОС 7. Спустя 10 минут отсутствия напряженной деятельности, наномашины, присутствующие в Подкожной Броне, восстанавливают ОС как тела, так и головы до полного уровня ОС.","short":"Лучшая Подкожная Броня, чем все остальные на рынке.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-eafe06ec","name":"Скрытая кобура","category":"Внешние Импланты","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Кобура внутри тело пользователя, может хранить оружие, которое может быть скрыто. Его можно скрыть без проверки. Оружие можно вытащить из скрытой кобуры без действия, если оно имплантировано в легкодоступное место на теле. Вы можете достать его из бедра, если только вы не носите штанов.","short":"Кобура внутри тело пользователя, может хранить оружие, которое может быть скрыто.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Скрытность"]},{"id":"c-5b91a81e","name":"Тканекожа","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Тело и голова бронированы всегда на уровне ОС 7. Ваша ОС определяется самым высоким предметом брони. Кроме того, всякий раз, когда ваша получает урон в каком-либо месте, все ваши предметы брони в этом месте получают урон одновременно (например, тканекожа головы и шлем). Когда вы успешно завершаете 1 день отдыха (исцеления), наномашины, присутствующие в коже, восстанавливают 1 ОС тела и головы.","short":"Тело и голова бронированы всегда на уровне ОС 7.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Защита"]},{"id":"c-d6f29868","name":"Тяжелая Подкожная Броня","category":"Внешние Импланты","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":5000,"priceLabel":"5000eb (Роскошь)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Стандартная подкожная броня больше не подходит, а Тканекожа считай что мусор! Чтобы не отставать от огневой мощи, которой обладают люди в наши дни, тебе нужны крепкие бронепластины под кожей. Большие, тяжелые, останавливающие все пули. Является Боргированием. Внешний киберимплант. Подкожная броня. Для установки требуется ТЕЛО 10, если только на пользователе нет корпуса ПКТ. Дает 13 ОС для тела и головы. Пользователь получает штраф к броне -2 к РЕА, ЛВК и СКО, если он не имеет ТЕЛО 14 или выше или если пользователь не перешёл на ПКТ. Тяжелая Подкожная Броня содержит наноботов, которые восстанавливают ее на 1 очко потерянных ОС в конце каждого дня, если она не теряла ОС в этот день. Примечание: При установке на корпус ПКТ Тяжелая Подкожная Броня обычно не является подкожной, а действует как кожа пользователя, обладая осязанием.","short":"Стандартная подкожная броня больше не подходит, а Тканекожа считай что мусор!","source":"Переходи на металл","requires":["ПКТ"],"body":10,"slots":0,"capacity":null,"role":null,"tags":["Защита"]},{"id":"c-3264106d","name":"Киберрука","category":"КиберРука","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Замена руки. Не обязательно в паре. Имеет 4 слота для опций киберруки или киберконечности. Изначально поставляется с предустановленной Стандартной Кистью, которая не требует Потери Человечности и не занимает слот киберруки.","short":"Замена руки.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":4,"role":null,"tags":[]},{"id":"c-daf974a6","name":"Нео-Советская КиберРука","category":"КиберРука","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100eb (Премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Замена руки. Не обязательно парная. Нео-Советская Киберрука имеет 3 слота опций Киберруки или Киберконечности и поставляется со Стандартной Кистью, которая не провоцирует Потерю Человечности и не занимает слот для опций Киберруки. Без ТЕЛ 8 или выше, вы получаете -1 ко всем броскам, которые требуют использования этой руки. Все опции, установленные в руке, всегда видны невооруженным глазом, когда она раскрыта, из-за ее неэффективной и выпуклой конструкции. Сюда входят и те варианты оружия, которые считались бы скрытыми в другой Киберруке. Нео-Советская Киберрука всегда распознается как Киберрука, даже с покрытием РеалскинTM.","short":"Замена руки.","source":"ЧерныйХром","requires":[],"body":8,"slots":0,"capacity":3,"role":null,"tags":["Восприятие","Скрытность"]},{"id":"c-b9d80a8b","name":"Радлайн Киберрука-Дугомет “Блицкриг”","category":"КиберРука","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (Оч.Дорогое)","humanity":14,"humanityLabel":"14(4d6)","desc":"Киберрука. Не обязательно парная. Имеет 0 слотов модулей Киберруки или Киберконечности. В руку не встроена кисть, поэтому ей нельзя ничего держать. Это изготовленная на заказ киберрука представляет собой Одноручный Экзотический Дробовик низкого качества, стреляющий с помощью навыка Оружие Крупного Калибра вместо навыка Тактическое оружие. С механической точки зрения, Дугомет — это дробовик, который может стрелять только с использованием альтернативного режима Выстрела Дробью, но при этом наносит 4d6 вместо 3d6 урона. Кроме того, вместо того, чтобы использовать боеприпасы, при каждом выстреле это оружие расходует один из 32 зарядов от легко перезаряжаемого (1 час) фирменного Аккумуляторного блока Радлайн МагнаСлот (100eb, входит в комплект при каждой покупке). Урон, наносимый этим оружием, не может нанести Критического Повреждения и не повреждает броню. Если урон, нанесенный этим оружием, уменьшит ПЗ цели до 1, то она Теряет Сознание с 1 ПЗ. Аккумулятор этого оружия можно извлечь и перезарядить в качестве Действия даже без свободной руки.","short":"Киберрука.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":0,"capacity":0,"role":null,"tags":["Бой","Защита"]},{"id":"c-bc446fbb","name":"Стандартная Кисть","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Напоминает обычную Кисть. При установке в мясную руку не учитывается при подсчете количества киберимплантов. Не занимает слот опций киберруки.","short":"Напоминает обычную Кисть.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-2eb6a6ab","name":"КиберКисть с модульными пальцами","category":"КиберРука","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Киберруки. Может быть установлен в качестве единственного киберимпланта в мясной руке. Вмещает до 5 Киберпальцев. Каждая покупка поставляется с пятью стандартными Киберпальцами. Дополнительные Киберпальцы продаются отдельно.","short":"Опция Киберруки.","source":"ЧерныйХром","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-32f7f0d7","name":"КиберКисть Энтузиаста с Модульными пальцами","category":"КиберРука","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":14,"humanityLabel":"14(4d6)","desc":"Боргирование. Опция Киберруки. Требует 2 слота опций. Содержит место для 8 киберпальцев. В комплект поставки входят 8 стандартных киберпальцев. Дополнительные киберпальцы продаются отдельно. Пальцы установленные в эту кисть причинают ПЧ от установки, но не влияют на МАКС ЧЕЛ пользователя.","short":"Боргирование.","source":"ЧерныйХром","requires":[],"body":null,"slots":2,"capacity":null,"role":null,"tags":[]},{"id":"c-091290d5","name":"Профессиональная Киберкисть Dynalar","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Киберруки. По сути, это стандартная киберкисть, способная беспроводным способом более эффективно взаимодействовать с элементами управления специально модернизированных электронных устройств, позволяя удаленно печатать, перемещать курсор и т.д. Пользова тель все равно должен находиться на расстоянии прикосновения к соответствующему устройству. Может быть установлен как единственная опция импланта в мясной руке.","short":"Опция Киберруки.","source":"Мешай Напитки","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-dcae2999","name":"Большие костяшки","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Армированные костяшки. Среднее Оружие Ближнего Боя (2d6, 2 СКА), можно скрыть без проверки. При использовании, рука не может что-то держать. Может быть установлен в качестве единственного киберимпланта в мясной руке.","short":"Модуль Киберруки.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Скрытность"]},{"id":"c-490ca06f","name":"Кибердека","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Кибердека намертво устанавливается в Киберруку. Необходимую для установки Кибердеку должен предоставить пользователь. Помимо того, что теперь ты никогда не потеряешь свою Кибердеку, в ней также появляется +1 дополнительный слот, в который можно установить Программы или Оборудование. При попытке выдернуть Кибердеку из Киберруки, она ломается без возможности починить, но программы и оборудование которые были на ней, можно восстановить. Требуется Киберрука и 3 слота модулей. Для работы кибердеки требуются Личный Порт и Нейролинк.","short":"Кибердека намертво устанавливается в Киберруку.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Нетраннинг"]},{"id":"c-c1c62f65","name":"Обновленная Интегрированная Кибердека","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Добавляет Кибердеке, ранее уже интегрированной в киберруку пользователя, один дополнительный слот, который можно использовать для Программ или Оборудования. Можно обновить только Кибердеку интегрированную в киберруку, установленную на той же киберруке.","short":"Опция Киберруки.","source":"ЧерныйХром","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Нетраннинг"]},{"id":"c-91e6da77","name":"Рукохват","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Потратив Действие, пользователь запускает крюк, который закрепится на любом прочном объекте на расстоянии до 30 метров. Трос выдерживает вес в два раза больше веса пользователя и имеет 10ПЗ. Пользователь игнорирует штрафы передвижения, взбираясь по тросу. Трос можно отпустить, не тратя Действие, даже при подъёме. Во время использования рука не может что-то держать. Неэффективен как оружие, нельзя использовать для Захвата противника. Требуется Киберрука.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Мобильность"]},{"id":"c-3185d4ef","name":"Медсканер","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Сканер с помощью датчиков и контактов диагностирует травмы и заболевания, помогая в экстренных ситуациях, не требующих навыка “Хирургия\". Добавляет пользователю +2 к Навыкам: Первая Помощь и Парамедик. Требуется Киберрука и 2 слота модулей. Множественная установка не даёт никаких преимуществ.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-c3c3803d","name":"Выкидной гранатомёт","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Одноручный гранатомет с одной гранатой в магазине, установленный в киберруку и несовместимый со всеми оружейными модификациями, кроме коннектора Смартлинка. Гранатомет можно успешно спрятать без проверки, а также открыть и закрыть без действия. Пока оружие \"вскинуто\", пользователь не может ничего держать в этой руке. Требуется Киберрука и 2 слота модулей.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-2b4d3547","name":"Выкидное оружие ближнего боя","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Одноручное легкое, среднее или тяжелое оружие ближнего боя (которое не обязательно должно быть скрываемым до установки) устанавливается в Киберруку так, чтобы его можно было успешно скрыть без проверки, а также достать и убрать без действия. Пока оружие \"вскинуто\", пользователь не может ничего держать в этой руке. Требуется Киберрука и 2 слота модулей.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Скрытность"]},{"id":"c-7618cc96","name":"Выкидной щит","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Пуленепробиваемый щит, который скрыт, внутри киберруки. Его можно достать или сложить без действия, если у щита больше 0 ПЗ. Когда щит вынут из руки, вы не можете использовать эту руку ни для чего другого, и не можете держать в руке ничего, кроме щита. Пуленепробиваемый щит, установленный внутри киберруки, легко снимается и заменяется другим пуленепробиваемым щитом для удобства чистки и ремонта. Требуется Киберрука и 3 слота модулей. См. раздел \"Использование щитов\" на СТР. 183.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Скрытность"]},{"id":"c-a8563954","name":"Выкидное оружие дальнего боя","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Одноручное дальнобойное оружие (которое не обязательно должно быть скрываемым до установки), выбранное пользователем, устанавливается в Киберруку (вместе с любыми оружейными модулями, прикрепленными к нему) так, что его можно успешно скрыть без проверки, а также достать и убрать без действия. Пока оружие \"вскинуто\", пользователь не может ничего держать в этой руке. Требуется Киберрука и 2 слота модулей.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Скрытность"]},{"id":"c-7c3f6ba0","name":"Быстросъёмное крепление","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Киберруку можно установить в свободное гнездо или снять с помощью действия. При первой установке новой Киберруки, при помощи быстросменного крепления или иным способом, вы всегда теряете человечность. Прикрепление киберруки, которую вы уже использовали с помощью быстросменного крепления к этому не приводит. Требуется Киберрука.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-a7840b51","name":"Царапки","category":"КиберРука","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (Премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль Киберруки. Искусственные ногти из углеродного стекла. Лёгкое оружие ближнего боя (1d6, 2 СКА), можно спрятать без проверки, о также выдвинуть или убрать без действия. Можно установить в мясную руку как единственный киберимплант.","short":"Модуль Киберруки.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-763907bf","name":"Потрошители","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Вариант киберруки. Удлиняемые когти из углеродного стекла. Среднее оружие ближнего боя (2d6, 2 СКА), которое можно прятать без проверки. При использовании рука должна быть свободна. Можно установить в мясную руку как единственный киберимплант.","short":"Вариант киберруки.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-ca77bb5d","name":"Плечевая камера","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Выдвижная камера на плече, отслеживает всё независимо от пользователя, записывает аудио и видео на встроенную щепку или связанный агент. Можно достать или спрятать без проверки и действия. Требуется Киберрука и 2 слота модулей.","short":"Модуль Киберруки.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие","Мобильность"]},{"id":"c-1bf5c3bf","name":"Слайсы да Кубики","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Моноструна, имплантированная в большой палец. Среднее оружие ближнего боя (2d6, 2 СКА), которое можно прятать без проверки. Нельзя ничего держать в руке при использовании. Можно установить в мясную руку как единственный киберимплант.","short":"Модуль Киберруки.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-488e52c1","name":"Смартлинк","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Подкожная пластина под ладонью для подключения умного оружия. Альтернатива личному порту. Можно установить, как единственный имплант в мясной руке. Требуется Нейролинк, занимает слот в импланте Нейролинк","short":"Модуль Киберруки.","source":"КорБук","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-5a5469e3","name":"Техсканер","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Диагностирует механизмы и электронику, помогая пользователю в ремонте и техобслуживании. Пользователь добавляет +2 к навыкам Знание Техники, Кибертехника, Автомобильные Технологии, Морские Технологии, Авиационные Технологии, Злектроника/Безопасность и Оружейник. Требуется Киберрука и 2 слота модулей. Многократная установка этой опции не дает никаких дополнительных преимуществ.","short":"Диагностирует механизмы и электронику, помогая пользователю в ремонте и техобслуживании.","source":"КорБук","requires":["Киберрука"],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-12741f8a","name":"Рука-мультитул","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. В пальцах находятся отвертка, гаечный ключ, небольшая дрель и т.д. Теперь никуда без Мультитула! Можно установить в мясную руку как единственный киберимплант.","short":"Модуль Киберруки.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-418b3a25","name":"Когти росомахи","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Модуль Киберруки. Выдвижные когти из углеродного стекла на костяшках пальцев. Тяжелое оружие ближнего боя (3d6, 2 СКА), которое можно спрятать без проверки. При использовании, кок оружие, нельзя ничего держать в руке. Можно установить в мясную руку как единственный киберимплант.","short":"Модуль Киберруки.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Мобильность"]},{"id":"c-4234afca","name":"Лампа-Вспышка","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Требуется 2 слота для Опций. В качестве действия пользователь может заставить цель с функционирующими мясными глазами или кибероптикой в радиусе 25 м сделать проверку СЛ15 Сопротивления пыткам/наркотикам. Для этого действия проверка не требуется. Если цель терпит неудачу, она получает критическое повреждение \"\"Повреждение Глаза\"\" на 1 минуту. Достаточная защита, например, Антиослепление Киберглаз, защищает от этого эффекта.","short":"Опция Киберруки.","source":"ЧерныйХром","requires":[],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Восприятие","Защита"]},{"id":"c-f217b4eb","name":"Выкидной Сеткомет","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Требует 3 слота опций. На Киберруку устанавливается Экзотический одноручный Сеткомет. Сеткомет содержит 1 сеть в своем магазине и стреляет с 1 СКА, используя навык Тактическое оружие и таблицу Дальность Стрельбы из Дробовика, за исключением того, что он не может поразить цель на расстоянии более 25 м. Сеткомет можно успешно спрятать без Проверки, а также вытащить и спрятать без Действия. Пока оружие \"\"вскинуто\"\", пользователь не может держать что-либо в этой руке. При попадании сеть захватывает цель. Одновременно цель может быть схвачена только одной сетью. Пока цель захвачена сетью, она не может использовать свое Перемещение, а также не может использовать оружие, требующее двух рук, и получает -2 ко всем физическим действиям до тех пор, пока остается в сети. Сеть имеет 15 ПЗ и безвозвратно уничтожается, когда достигает 0 ПЗ. Внешняя стрельба из Оружия Дальнего Боя в развернутую сеть наносит одинаковый урон и сети, и захваченной ею цели. Для высвобождения из сети требуется проверка Акробатики СЛ13, которую может выполнить только цель внутри сети, или проверка Рукопашного Боя СЛ13, которую может пройти любой. Успех любого из них безвозвратно разрушает сеть. Сменные сети стоят 50eb (Ценное) каждая.","short":"Опция Киберруки.","source":"ЧерныйХром","requires":[],"body":null,"slots":3,"capacity":null,"role":null,"tags":["Бой","Мобильность","Нетраннинг"]},{"id":"c-b8cc700e","name":"Выкидной Дробовик","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1000eb (Оч.Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Требует 3 слота опций. В Киберруку устанавливается дробовик с 2 патронами в магазине, несовместимый со всеми модификациями оружия, кроме Коннектора Смартлинка. Дробовик можно успешно спрятать без Проверки, а также вытащить и убрать без Действия. Пока оружие \"\"поднято\"\", пользователь не может держать что-либо в этой руке.","short":"Опция Киберруки.","source":"ЧерныйХром","requires":[],"body":null,"slots":3,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-8172584e","name":"Цепной потрошитель","category":"КиберРука","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500eb (Дорогое)","humanity":14,"humanityLabel":"14(4d6)","desc":"Модуль Киберруки. Одноручное Очень Тяжелое ОББ устанавливается в киберруку так, чтобы его можно было достать и убрать без действия. Пока оружие \"\"поднято\"\", пользователь не может ничего держать в руке. Запуск, в качестве Действия, активирует Потрошителя, и он будет оставаться активированным до тех пор, пока не будет убран или опущен в качестве Действия. Во взведенном состоянии Цепной Потрошитель — Одноручное Экзотич- еское Очень Тяжелое Оружие Ближнего Боя превосходного качества. Занимает 4 слота опций.","short":"Модуль Киберруки.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":4,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-a5919e70","name":"Киберматрикс Гэнг Джаззлер","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Мощная электродная игла, которая может быть спрятана в руке без проверки. Когда пользователь совершает Удушение цели во время Захвата, вместо нанесения урона он может потратить весь заряд легко перезаряжаемой батареи 50eb (Ценное) (1 час), спрятанной в руке, заставив цель попытаться выполнить проверку СЛ13 \"\"Сопротивление пыткам/наркотикам\"\". Если цель проваливает проверку, она Теряет Сознание независимо от общего количества Пунктов Здоровья. Бессознательное состояние длится одну минуту. Может быть установлен в качестве единственного Кибероборудования в мясной руке.","short":"Опция Киберруки.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Защита"]},{"id":"c-6de8d52b","name":"Псайберстаф УотчМэн","category":"КиберРука","place":"Молл","surgeryDV":13,"installCost":100,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Полнофункциональный Агент с откидным экраном (СМ. CP:R СТР. 352), встроенный в киберруку.","short":"Модуль Киберруки.","source":"12 Дней КиберРождества","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-f313a29a","name":"Рейвен МикроКибернетикс МикроВалдо","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1000eb (Оч.Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Набор паукообразных зондов превращает вашу руку в монстра хирургической точности. Пусть МикроВалдо станет вашим новым хирургическим ассистентом. Модуль Киберруки. Опция Нейролинка. Медтех, использующий МикроВалдо, получает +1 к Хирургии.","short":"Опция Киберруки.","source":"12 Дней КиберРождества","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-77a60a79","name":"КиберПодушка","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":0,"humanityLabel":"Нет","desc":"Опция Киберруки. Хоть киберподушка и впитывает влагу и удобна, она не дает никаких преимуществ, кроме того, что позволяет вздремнуть в любом месте. Многочисленные установки не дают ничего, кроме облегчения процесса засыпания.","short":"Опция Киберруки.","source":"ККТОК","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-fd3900e5","name":"Голопроектор Для Ладони","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Голограммный проектор, встроенный в ладонь пользователя. При подключении к агенту может выдавать потенциально интерактивную голографическую проекцию размером примерно с банку содовой. Может быть установлен в качестве единственного импланта в мясной руке.","short":"Голограммный проектор, встроенный в ладонь пользователя.","source":"ККТОК","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-11519f13","name":"Персональный Разогреватель Киббла","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Персональная Упаковка Киббла, разогревающая его до требуемой температуры, чтобы получить хрустящую корочку. Требуется Киберрука.","short":"Модуль Киберруки.","source":"ККТОК","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-345b7996","name":"Ускоренный Защищенный Встроенный Персональный Шредер","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберруки. Коммерческий шредер для поперечной резки, скрытый в киберруке, с внутренним резервуаром для хранения отходов. Требуется Киберрука.","short":"Модуль Киберруки.","source":"ККТОК","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Скрытность"]},{"id":"c-770d741f","name":"Газомет от Стремительной охраны ИНК","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Аэрозольная Газовая Пусковая Установка, заряженная 3 дозами уличного наркотика или 3 ампулами с ядом или биотоксином. Газомёт можно успешно спрятать без проверки. Механически он работает как одноручный экзотический дробовик с одним зарядом, стреляющий только с использованием альтернативного режима стрельбы \"\"Выстрел дробью\"\". Вместо нанесения урона, газомёт вызывает эффект вещества, которым заряжен, к любой пораженной выстрелом цели. Каждый выстрел требует полной зарядки и полностью разряжает оружие. Требуется Киберрука и занимает 2 слота модулей.","short":"Опция Киберруки.","source":"АптекаХорнета","requires":["Киберрука"],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-dd65482d","name":"Интегрированный КиберСканер","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Опция Киберруки. Требует 2 слота опций. Интегрированный киберсканер в Киберруку. Показания выводятся на LED панель встроенную в руку, но также могут быть на правлены на сопряжённый Хирон или Агент. Киберсканер может сканировать цель в пределах 2 м/ярдов и выводить данные обо всём установленном хроме. Сканирование занимает 1 минуту и цель должна быть неподвижна на всём протяжении. Если хоть что-то из обнаруженного оборудования экранировано от ЭМИ, тех. улучшено или является уникальным/неизвестным/кастомным киберсканер выводит ошибку.","short":"Опция Киберруки.","source":"12 дней Снаряждества","requires":[],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Восприятие","Мобильность"]},{"id":"c-73c21553","name":"Быстрые Пальцы Rocklin Augmentics","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":250,"priceLabel":"250eb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция для киберруки. Киберкисть. Может быть установлена как единственный имплант в обычной руке. Если у пользователя установлено два или более модулей Быстрых Пальцев, он автоматически получает +1 к проверкам по следующим навыкам — так, словно получил вспомогательную проверку непосредственно от рук: Скрытие/Обнаружение Предмета, Акробатика (только при манипуляциях руками), Первая помощь, Подделка, Язык (жестовый), Парамедик, Вскрытие замков, Карманник. Бонусы от вспомогательных проверок не складываются.","short":"Опция для киберруки.","source":"THE 12 DAYS OF REDMAS","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие","Мобильность","Скрытность"]},{"id":"c-bb92439d","name":"Hello Cutie Mono-Paw","category":"КиберРука","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Сверхострые втягивающиеся кошачьи когти с мономолекулярными наконечниками. Мяу-больно! Изначально производились Kendachi в рамках совместного проекта с линейкой Hello Cutie от Sanroo, но с тех пор эта киберлапка перекочевала в арсенал топовых Техников, правда, чаще без розового неона оригинальной версии. Опция для Киберруки. Среднее Оружие Ближнего Боя Отличного Качества, наносящее 1d6 урона и может быть спрятано без проверки. Урон от оружия полностью игнорирует броню, если её ОС ниже 11 Если ОС11 и выше — урон считается как обычно. Пока Моно-Лапка активна, персонаж не может держать ничего в руке, в которую она установлена.","short":"Сверхострые втягивающиеся кошачьи когти с мономолекулярными наконечниками.","source":"THE 12 DAYS OF CUTIEMAS","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой","Защита"]},{"id":"c-d651f16d","name":"Кибернога","category":"КиберНога","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100eb(премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Имплант ноги. Не обязательно устанавливать пару. В Киберноге имеется 3 слота для модулей Киберноги или Киберконечностей. Оно поставляется с предустановленной Стандартной Стопой (не занимает слот в киберноге, не вредит Человечности). Большинство опций должно быть приобретено дважды (установлено в обе ноги) и синхронизировано. (Каждый модуль покупается отдельно. Потеря Человечности рассчитывается отдельно для каждого модуля).","short":"Имплант ноги.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":3,"role":null,"tags":[]},{"id":"c-5c69da76","name":"Визард Технолоджис Киберноги Романовой","category":"КиберНога","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (Очень дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Парные Киберноги. Они заменяют обе ноги, но Цена и Потери Человечности считаются как за 1 имплант, однако Критические Повреждения и ремонт считаются для каждой ноги раздельно. Каждая Кибернога имеет 3 слота Опций Киберноги или Киберконечностей. В каждую Киберногу встроен Коготь (СМ. CP:R СТР. 367), который не провоцирует Потерю Человечности и не занимает слот Опции Киберноги. Когти нельзя удалить, не повредив Киберноги до неузнаваемости.","short":"Парные Киберноги.","source":"12 ДнейКибеооруждества","requires":[],"body":null,"slots":0,"capacity":3,"role":null,"tags":["Бой"]},{"id":"c-cce9d77e","name":"Rocklin Augmentics Skydrivers","category":"КиберНога","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1000eb (Очень дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Парные Киберноги. Они заменяют обе ноги, но Цена и Потери Человечности считаются как за 1 имплант, однако Критические Повреждения и ремонт считаются для каждой ноги раздельно. Каждая содержит 2 слота для опций киберконечности или киберимплантов. В комплекте — встроенные прыжковые усилители, не требующие слота и не увеличивающие потерю человечности. Удалить усилители невозможно без разрушения киберног. Если пользователь за этот ход преодолел не менее 4 м, и после этого атакует ногами (драка или боевые искусства) по укрытию (и только укрытию), урон увеличивается на 3d6.","short":"Парные Киберноги.","source":"THE 12 DAYS OF REDMAS","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Мобильность"]},{"id":"c-c33edd39","name":"Стандартная Стопа","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb(премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Напоминает обычную Стопу. При установке в мясную ногу не учитывается при подсчете количество киберимплантов, установленных в ноги. Не занимает слов в киберноге.","short":"Напоминает обычную Стопу.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-715de3b2","name":"Цепкая подошва","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Модуль Киберноги. Подошвы покрыты самым технологичным сцепляющим материалом. Обычный штраф передвижения, для лазания не учитывается. Требуется две сопряжённые Киберноги.","short":"Модуль Киберноги.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-f24f4d66","name":"Прыжковый ускоритель","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Гидравлические ноги, отменяющие штраф к прыжком. Требуется две сопряженные киберноги, занимает 2 слота модулей.","short":"Гидравлические ноги, отменяющие штраф к прыжком.","source":"КорБук","requires":[],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-99aaf2d2","name":"Стопа скейт","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Стопа с колесиками. Можно скрыть. Увеличивает скорость на 6 м при использовании действия “бег\". Требуется две сопряженные киберноги.","short":"Стопа с колесиками.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Мобильность","Скрытность"]},{"id":"c-8c9e92f4","name":"Коготь","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Клинок в стопе. Лёгкое оружие ближнего боя. Можно скрыть без проверки. Можно установить, как единственный имплант в мясной ноге.","short":"Клинок в стопе.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Скрытность"]},{"id":"c-d0d1248f","name":"Ласты","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500eb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Тонкая перепонка между пальцами. Отменяет штраф при плавании. Требуется две сопряженные киберноги.","short":"Тонкая перепонка между пальцами.","source":"КорБук","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":[]},{"id":"c-006658ff","name":"Идеальная Киберстопа","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":100,"priceLabel":"100eb(премиум)","humanity":2,"humanityLabel":"2 (1d6/2)","desc":"Модуль для Киберноги. обеспечивает превосходную поддержку и помогает микрорегулируемому носку сделать любую обувь в вашей коллекции удобной для носки. В паре это импланты сводят к нулю любые штрафы, которые вы можете понести из-за ношения плохо сидящей или неподходящей обуви в ситуации, не связанной с модой. Может быть установлено как единственный имплант в мясной ноге.","short":"Модуль для Киберноги.","source":"ККТОК","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-dad13394","name":"Устройство нулевой гравитации","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1000eb (Очень дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Серия \"\"Двигайся Точно\"\" позволяет пользователю точно контролировать свои движения, находясь в невесомости. Опция для Киберног. При ее использовании пользователь лишается всех штрафов на СКО, связанных с пребыванием в невесомости. Устройства Нулевой Гравитации работают на топливных баках, которые стоят 100еb каждый и должны быть заменены после 24 часов использования. Требуются две киберноги, должны быть спарены и занимают 2 слота для опций.","short":"Серия \"\"Двигайся Точно\"\" позволяет пользователю точно контролировать свои движения, находясь в невесомости.","source":"ПНМ","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-7d0580e7","name":"Стопа-Трансформер","category":"КиберНога","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1000eb (Очень дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Никогда больше не наклоняйтесь, чтобы поднять что-то. Опция для Киберног. В качестве действия пользователь может трансформировать свою киберногу так, чтобы она работала как киберрука, превращая киберстопу в киберкисть. Действием можно обратить трансформацию вспять. Во время трансформации пользователь получает -4 к СКО (минимум 1), если только он не находится в невесомости.","short":"Никогда больше не наклоняйтесь, чтобы поднять что-то.","source":"ПНМ","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-912e5a5c","name":"Закаленное экранирование","category":"Покрытие","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000еЬ (0. дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция покрытия киберконечности. Конечность и установленные опции не могут быть выведены из строя с помощью ЭМИ или противопрограммным чёрным льдом. Требуется кибернога или киберрука.","short":"Опция покрытия киберконечности.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Нетраннинг"]},{"id":"c-d82a3d79","name":"Пластиковое покрытие","category":"Покрытие","place":"Молл","surgeryDV":13,"installCost":100,"price":0,"priceLabel":"l00eb (Премиум)","humanity":0,"humanityLabel":"Нет","desc":"Опция покрытия киберконечности. Пластиковое покрытие для конечности, доступное в большом разнообразии цветов и узоров. Требуется кибернога или киберрука, не занимает слот.","short":"Опция покрытия киберконечности.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-133552f9","name":"Покрытие Реалскин™","category":"Покрытие","place":"Молл","surgeryDV":13,"installCost":100,"price":500,"priceLabel":"500еЬ (Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Опция покрытия киберконечности. Покрытие из искусственной кожи для конечности. Требуется кибернога или киберрука, не занимает слот","short":"Опция покрытия киберконечности.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-e8dd3ec5","name":"Покрытие Суперхром®","category":"Покрытие","place":"Молл","surgeryDV":13,"installCost":100,"price":1000,"priceLabel":"1,000еЬ (0. дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Опция покрытия киберконечности. Блестящее металлическое покрытие для конечности. +2 к Гардеробу и стилю. Требуется кибернога или киберрука, не занимает слот.","short":"Опция покрытия киберконечности.","source":"КорБук","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Социалка"]},{"id":"c-489081a7","name":"Покрытие для спонсоров","category":"Покрытие","place":"Молл","surgeryDV":13,"installCost":100,"price":50,"priceLabel":"50eb (Ценное)","humanity":0,"humanityLabel":"Нет","desc":"Опция покрытия киберконечности. Киберконечность покрыта иллюстрированной рекламой. При условии, что пользователь остается на хорошем счету у его спонсора, что может включать воздержание от сомнительного поведения, участие в мероприятиях, указанных спонсором, и демонстрацию конечности без одежды (да, у них есть датчики) в течение определенного времени каждого дня, пользователь получает 20eb первого числа каждого месяца. Чаше всего, пользователь вынужден оплачивать спонсорское покрытие заранее, как часть своего контракта, но не все контракты включают этот пункт. Известны случаи, когда спонсоры пытались отобрать всю руку, если пользователь нарушал условия договора. Требуется Киберрука или Кибернога, но не занимает слот опций.","short":"Опция покрытия киберконечности.","source":"ККТОК","requires":["Киберрука"],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-0ad87d29","name":"ОБНОВЛЕННАЯ УСИЛЕННАЯ КИБЕРКОНЕЧНОСТЬ","category":"Универсальные Опции Конечностей","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Киберконечности. Повышенное гидравлическое резервирование и укрепление, добавленные к киберконечности, позволяют функционировать даже при экстремальных нагрузках. Эта конечность невосприимчива к критическому повреждению \"\"Перелом Ноги\"\", если это кибернога, или к критическому повреждению \"\"Перелом Руки\"\", если это киберрука. ГМ решает, какая конечность будет целью, когда Персонаж получает Критическое Повреждение, если не указано иное.","short":"Опция Киберконечности.","source":"ЧёрныйХром","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":[]},{"id":"c-7a2f543b","name":"Экстра-Сочленение конечности","category":"Универсальные Опции Конечностей","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500еb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Опция Киберконечности. Пользователь получает бонус +2 к проверкам Акробатики. На Киберконечность можно установить только одно такое экстра- сочленение. Пользователь может получить выгоду только от четырех таких Киберконечностей одновременно, что дает общий возможный бонус +8.","short":"Опция Киберконечности.","source":"ЧёрныйХром","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-5056a696","name":"Берсерк","category":"Импланты 2070х годов","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Имплант гормональной регуляции, предназначенный для улучшения “Бей или беги” реакции пользователя. Опция Нейролинка. Этот имплантат по команде вызывает мощный выброс адреналина. При активации в качестве Действия пользователь игнорирует эффекты состояний «Тяжелое и Смертельное Ранение в течение 60 секунд (20 Раундов) с одним исключением: Смертельно раненые персонажи все равно должны делать спасброски от смерти. По истечении периода активации имплантат нельзя активировать повторно в течение 1 часа.","short":"Имплант гормональной регуляции, предназначенный для улучшения “Бей или беги” реакции пользователя.","source":"Edgerunners Mission Kit","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Мобильность"]},{"id":"c-ab577e84","name":"ИнтраЛЕД","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500еb (Дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Ликвидатор Единичного Доступа - Система созданная для укрепления защиты от Быстрого Взлома. Опция Нейропорта. При каждой установке (максимум 3) в Нейропорт пользователя устанавливается один Заслон, обеспечивающий дополнительную линию защиты. Кроме того, с каждой установкой ИнтраЛьда СЛ всех Заслонов в Нейропорте пользователя увеличивается со Сл 6 при первой установке до Сл 8 при второй, а при третьей установке до Сл 10.","short":"Ликвидатор Единичного Доступа - Система созданная для укрепления защиты от Быстрого Взлома.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Восприятие","Защита","Нетраннинг"]},{"id":"c-27174ea7","name":"Клинок Богомола","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":500,"priceLabel":"500еb (Дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Эти легендарные лезвия созданы с учетом смертоносности и скрытности. Они столь же эффективны, сколь и узнаваемы. Вариант Киберруки. Требуется 2 слота для опций Киберруки. Одноручное Тяжелое ОББ Отличного Качества, которое можно успешно спрятать без проверки, а также вытащить и спрятать без Действия. Пока оружие выдвинуто, пользователь не может ничего держать в этой руке. При покупке дважды и установке в две отдельных киберруки пользователь может свести на нет обычный штраф за передвижение при лазании, пока у него оба оружия выдвинуты.","short":"Эти легендарные лезвия созданы с учетом смертоносности и скрытности.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Бой","Мобильность","Скрытность"]},{"id":"c-27dfe796","name":"Мега-Диск","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Имплантат, увеличивающий способность мозга хранить и обрабатывать информацию, связанную с Нетраном. Опция Нейролинка. Требуется Слот Нейропорта для Кибердеки. Каждая установка содержит слот Опции Оборудования для Кибердеки. Все Опции, установленые на Мега-Диск пользователя, считается установленным на любой Кибердеке, установленной в Слот Нейропорта для Кибердеки пользователя. Пользователь с двумя или более Мега-Дисками получает одно дополнительное Сетевое Действие каждый ход, когда он физически подключен к точке доступа вручную через свой Личный Разъем.","short":"Имплантат, увеличивающий способность мозга хранить и обрабатывать информацию, связанную с Нетраном.","source":"Edgerunners Mission Kit","requires":["Нейролинк"],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Нетраннинг"]},{"id":"c-3bd434d5","name":"Моноструна","category":"Импланты 2070х годов","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Кнутообразная моноволоконная нить с режущей кромкой шириной всего в молекулу. Опция Киберруки. Кнут из мононити, который можно успешно спрятать без проверки. Одноручное Экзотическое Тяжелое ОББ, способное совершать рукопашные атаки на расстоянии до 6 м/ярдов (3 клетки). Каждый раз, когда мононить причиняет критическую травму, нападающий дважды бросает кубики по таблице критических травм и выбирает предпочитаемый вариант страдания своей жертвы.","short":"Кнутообразная моноволоконная нить с режущей кромкой шириной всего в молекулу.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-53a51a9f","name":"Нейропорт","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":7,"humanityLabel":"7 (2d6)","desc":"Современное чудо, Нейропорт — это набор управления кибероборудованием, наполненный дополнительными функциями, от голофона до HUD-дисплея. Нейропорт считается настолько безопасным и необременительным, что большинство детей имеют его. Обучение его использованию является частью многих программ начальной школы. Ранняя установка связана с лучшими результатами во взрослой жизни, но верно и обратное. Те, у кого нет Нейропорта, находятся в невыгодном положении по сравнению со своими сверстниками и имеют более низкий уровень образования и финансового успеха во взрослой жизни. Чтобы облегчить эту ситуацию или, говоря более цинично, получить от нее прибыль, семьям, которые не могут позволить себе нейропорт для своих детей, часто предлагаются хищнические кредиты под высокие проценты. Другие обращаются к Улице, чтобы найти другие, более доступные варианты для своих детей, доверяя риппердокам из переулков. Дополнительную информацию о нейропортах см. в «Edgerunner Handbook» Стандартный Нейропорт включает в себя следующее кибероборудование: • Нейролинк: проводная искусственная нервная система, базовое кибероборудование, необходимое для использования Нейроимплантов. Система имеет 5 слотов для опций Нейроимплантов, ни один из которых не занят другими функциями нейропорта. Ни одна из функций Нейропорта не требует дополнительного оборудования для работы или использования слотов опций где-либо у пользователя. • Голофон: полнофункциональный телефон с ограниченным доступом к CitiNet поисковику, звонками, текстовыми сообщениями и планировщику. Он управляется мозгом и не требует голосовых команд. • Биомонитор: этот имплантат отслеживает пульс, температуру, дыхание, уровень сахара в крови и другие показатели и постоянно передает эту информацию в HUD пользователя. • Виртуальность (или VR-зрение): позволяет пользователю воспринимать виртуальные презентации, представления и даже симуляции. Это также позволяет Нетраннерам в полной мере ощутить Сеть во время глубокого погружения. Это не позволяет пользователю испытать Брейнданс. • HUD (или Хирон): информация с голофона пользователя, биомонитора и другого кибероборудования проецируется в поле зрения пользователя посредством прямого подключения к его зрительному нерву. Программы, установленные в HUD, даже реагируют на мысли пользователя или дополнительные установленные базы данных, чтобы маркировать важные объекты и людей, предоставлять расшифровки разговоров и медиа и даже визуально переводить иностранные языки. • Два слота для о щепок (или разъемы для чипов): два разъема за ухом или на шее позволяют быстро установить до двух микросхем и считывать фрагменты данных (чипы памяти). • Личный порт (или интерфейсный разъем): выдвижной шнур, обычно встраиваемый в запястье, позволяющий пользователю напрямую подключаться к компьютерам.","short":"Современное чудо, Нейропорт — это набор управления кибероборудованием, наполненный дополнительными функциями, от голофона до HUD-дисплея.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":5,"role":null,"tags":["Мобильность","Нетраннинг"]},{"id":"c-e08e8b3c","name":"Рука Гориллы","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Классические и надежные улучшения для киберрук Опция Киберруки. Требуется 2 слота для опций Киберруки. Этот усиленный кулак можно использовать как Тяжелое ОББ Отличного Качества. Пользователь может держать оружие в этой руке, как если бы у него было ТЕЛО 11. При покупке дважды и установке в двух отдельных киберруках пользователь также может взламывать двери/передвигать толстое укрытие, Душить, совершать Бросок как если бы у него было ТЕЛО 11.","short":"Классические и надежные улучшения для киберрук Опция Киберруки.","source":"Edgerunners Mission Kit","requires":[],"body":11,"slots":2,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-dbfa6799","name":"Система запуска снарядов","category":"Импланты 2070х годов","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000еb (О. дорогое)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Универсальная система запуска взрывчатки у вас в руках (в более или менее буквальном смысле). Опция Киберруки. Боргирование. Требуется 2 слота опций Киберруки. В Киберруку установлен одноручная ракетница-гранатомет с одной ракетой/гранатой в магазине. Имплант несовместим со всеми опциями для оружия, кроме Смарт-Улучшения. При зарядке ракетой он действует как ракетная установка. При зарядке гранатой он действует как гранатомет. Его можно успешно спрятать без Проверки, а также вытащить и спрятать без Действия. Пока оружие выдвинуто, пользователь не может ничего держать в этой руке.","short":"Универсальная система запуска взрывчатки у вас в руках (в более или менее буквальном смысле).","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-46507d51","name":"Слот Нейропорта для Кибердеки","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":100,"priceLabel":"100еb (Премиум)","humanity":3,"humanityLabel":"3 (1d6)","desc":"Этот Слот, установленный на шее, подключает Кибердеку непосредственно в тело, значительно увеличивая радиус действия. Опция Нейропорта. Требуется Нейропорт. В задней части шеи пользователя установлен дополнительный специализированный слот для установки Кибердеки. К 2070 году все Кибердеки будут доступны в версиях для Нейропорта по той же цене, что и более традиционные форматы, однако такие деки не поддерживают Опции Оборудования. Любую Кибердеку, совместимую со Слотом Нейропорта для Кибердеки, можно установить/удалить в указанный порт в качестве Действия. При установке пользователь считается полностью подключенным к Кибердеке и получает преимущества любой Опции Оборудования, установленной в его костюме Бодивейт (или аналогичном). Радиус действия любой установленной Кибердеки увеличивается до 20 м/ярдов (10 квадратов) для подключения к обычным СЕТевым Архитектурам и до 50 м/ярдов (25 квадратов) для подключения к Нейропортам. Стены по-прежнему блокируют доступ, как обычно. Пользователь может быть подключен только к одной Кибердеке одновременно. Одновременно можно установить только один Слот Нейропорта для Кибердеки. Кибердеку необходимо приобретать отдельно.","short":"Этот Слот, установленный на шее, подключает Кибердеку непосредственно в тело, значительно увеличивая радиус действия.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":1,"capacity":null,"role":null,"tags":["Нетраннинг"]},{"id":"c-281acfed","name":"Эксперементальный Сандевистан Девида","category":"Импланты 2070х годов","place":"Госпиталь","surgeryDV":17,"installCost":1000,"price":250000,"priceLabel":"250,000 еb (Супер-Роскошь)","humanity":14,"humanityLabel":"14 (4d6)","desc":"Таких в мире всего несколько штук, и это стоило жизни как минимум двум людям. Ты уверен, что хочешь этого? Опция Нейролинка. Боргирование. Ускоритель. Требуется 2 слота опций Нейролинка. Каждый раз, когда пользователь активирует Экспериментальный Сандевистан, он получает 2d6 ПЧ. Активация не требует действия, даже во время боя. Если активирован в начале боя, пользователь немедленно попадает в начало очереди инициативы. Если он активирован во время боя, пользователь немедленно перемещается на вершину очереди инициативы. Если пользователь активирует Экспериментальный Сандевистан, в свой ход он может предпринять дополнительное Движение или другое Действие. Если Экспериментальный Сандевистан активируется пользователем с отрицательной Человечностью, то он получает количество урона, равное ПЧ, которую он испытывает. Этот урон наносится непосредственно в ПЗ и игнорирует броню, и не повреждает ее. Персонаж с отрицательной Человечностью впадает в Экстремальный Киберпсихоз, и его лист передается Мастеру, который отыгрывает его в соответствии с худшими наклонностями. Одновременно пользователю может быть установлена только один Ускоритель.","short":"Таких в мире всего несколько штук, и это стоило жизни как минимум двум людям.","source":"Edgerunners Mission Kit","requires":["Нейролинк"],"body":null,"slots":2,"capacity":null,"role":null,"tags":["Бой","Восприятие","Защита","Мобильность"]},{"id":"c-6cf5bd80","name":"Гидравлический Таран","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Ультрасовременная поршневая система облегчает выполнение сложных работ по сносу. Улучшение Руки Гориллы. Поршневые системы Руки Гориллы увеличивают урон, наносимый по укрытию (и только по укрытию), добавляя 3к6 к базовому урону оружия.","short":"Ультрасовременная поршневая система облегчает выполнение сложных работ по сносу.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-60a7f646","name":"Пневматические приводы","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Ряд поворотных пневматических приводов расширяет диапазон движений при выполнении деликатных задач максимальной жестокости. Улучшение Руки Гориллы. Пневматические приводы Руки Гориллы расширяют возможности пользователя точно нанести урон. Когда это оружие наносит критическую травму, бонусный урон этой критической травмы увеличивается на 5.","short":"Ряд поворотных пневматических приводов расширяет диапазон движений при выполнении деликатных задач максимальной жестокости.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Мобильность"]},{"id":"c-271abbc1","name":"Вольфрамовое укрепление","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500 eb (Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Точечное применение вольфрама улучшает суставы и внутреннюю структуру Рук Гориллы, что делает их идеальными для использования в армии и полиции. Улучшение Руки Гориллы. Дополнительное усиление Руки Гориллы превращает ее в комбинированное оружие, давая ей два режима: Тяжелое Оружие Ближнего Боя Отличного Качества (СКА 2, 3к6 урон) и Очень Тяжелое Оружие Ближнего Боя Отличного Качества (ROF 1, 4d6 урона). Пользователь должен решить, какой режим использовать при атаке оружием. Переключение между режимами не требует Действия.","short":"Точечное применение вольфрама улучшает суставы и внутреннюю структуру Рук Гориллы, что делает их идеальными для использования в армии и полиции.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-0e023bcf","name":"Двухсторонняя заточка","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Имея вторую режущую кромку, вы сможете резать глубже, чем когда-либо прежде. Улучшение Клинка Богомола. Дополнительная режущая кромка увеличивает шансы нанести противнику серьезную рану. Всякий раз, когда это оружие наносит критическую травму, пользователь дважды бросает кубик по таблице критических травм и выбирает более полюбившийся вариант страдания жертвы.","short":"Имея вторую режущую кромку, вы сможете резать глубже, чем когда-либо прежде.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-4fbe4ed9","name":"Мономолекулярное лезвие","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Лезвие оснащается мономолекулярной кромкой, что делает его настоящей монокатаной. Улучшение Клинка Богомола. Мономолекулярное лезвие позволяет Клину Богомола прорезать броню низкого уровня. Любой урон, наносимый этим оружием, полностью игнорирует броню цели, если она ниже 7 ОС (до уменьшения вдвое). С броней 7 ОС или выше по-прежнему взаимодействуют как обычно.","short":"Лезвие оснащается мономолекулярной кромкой, что делает его настоящей монокатаной.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Защита"]},{"id":"c-9576ed58","name":"Обтекаемость","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Лезвие уменьшено, чтобы уменьшить сопротивление, что делает его идеальным для любителей Ускоряющих имплантов. Улучшение Клинка Богомола. Кибернетически продвинутые пользователи получают значительные преимущества от более легкого и быстрого лезвия. Каждый раз, когда пользователь активно использует Ускоритель и тратит хотя бы одно очко Удачи на Атаку, совершенную с использованием этого оружия, он добавляет +1 к своей Проверке. Это в дополнение к любым другим полученным бонусам, включая бонус, полученный за трату Удачи.","short":"Лезвие уменьшено, чтобы уменьшить сопротивление, что делает его идеальным для любителей Ускоряющих имплантов.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Защита"]},{"id":"c-ae60b484","name":"Колючая проволока","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"По всей длине проволоки установлены мономолекулярные шипы, разрывающие плоть. Улучшение Моноструны. Мономолекулярные шипы, встроенные в струну, повышают вероятность нанесения поистине серьезной травмы. Всякий раз, когда это оружие наносит критическую травму, пользователь бросает трижды бросок по таблице критических травм (вместо двух) и выбирает более полюбившийся вариант страдания жертвы.","short":"По всей длине проволоки установлены мономолекулярные шипы, разрывающие плоть.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-36df68e9","name":"Электрошокер","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":500,"priceLabel":"500 eb (Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"В проволоку устанавливаются шоковые узелки, что позволяет использовать ее в менее смертельных целях. Улучшение Моноструны. Импульсы электричества проходят через шоковые узелки струны, превращая его в электрошокер. Если урон, нанесенный этим оружием, снизит ПЗ цели до значения менее 1, пользователь может вместо этого оставить цель без сознания с 1 ПЗ.","short":"В проволоку устанавливаются шоковые узелки, что позволяет использовать ее в менее смертельных целях.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой"]},{"id":"c-c3d5cb62","name":"Раскалённые лезвия","category":"Модули улучшения имплантов 2070х","place":"Клиника","surgeryDV":15,"installCost":500,"price":1000,"priceLabel":"1,000 eb (О. Дорогое)","humanity":0,"humanityLabel":"Нет","desc":"Струна усеяна сверхгорячими лезвиями для повышения эффективности против брони. Улучшение Моноструны. Раскалённая проволока более просто прорезает броню. Каждый раз, когда это оружие повреждает броню, оно вычитает 1 дополнительный пункт ОС.","short":"Струна усеяна сверхгорячими лезвиями для повышения эффективности против брони.","source":"Edgerunners Mission Kit","requires":[],"body":null,"slots":0,"capacity":null,"role":null,"tags":["Бой","Защита"]}];
